"use strict";

/**
 * Extended Compliance Frameworks
 *
 * Contains control definitions for 11 additional frameworks beyond the
 * core 3 (ISO 27001, SOC 2, DPDP) defined in compliance-report.service.ts.
 *
 * Each framework exports a getXxxControls() function returning control
 * definitions with guidance for the compliance configuration journey.
 */

// Re-use the types from the main service
interface ControlGuidance {
  learnMore: string;
  whyItMatters: string;
  controlType?: "platform" | "configurable" | "evidence";
  requiredActions: { action: string; configPath?: string; automated: boolean }[];
}

interface ControlDef {
  id: string;
  framework: string;
  title: string;
  description: string;
  category: string;
  guidance: ControlGuidance;
}

// ════════════════════════════════════════════════════════════════════════════════
// CMMC — Cybersecurity Maturity Model Certification (Levels 1-3)
// ════════════════════════════════════════════════════════════════════════════════

export function getCmmcControls(): ControlDef[] {
  return [
    { id: "AC.1.001", framework: "cmmc", title: "Limit system access to authorized users", description: "Limit information system access to authorized users, processes acting on behalf of authorized users, or devices.", category: "Access Control", guidance: { learnMore: "Only authenticated and authorized entities should access the system. This includes users, automated processes, and registered devices.", whyItMatters: "Unauthorized access is the most common attack vector. Without access controls, any threat actor can access sensitive CUI data.", controlType: "platform", requiredActions: [{ action: "Verify all API endpoints require authentication (automated — system checks that JWT auth middleware is active on every Express route, confirms authenticateToken/authenticateHybrid guards all non-public routes, and rejects unauthenticated requests with 401)", configPath: "/app/compliance?tab=controls&framework=cmmc&control=AC.1.001", automated: true }] } },
    { id: "AC.1.002", framework: "cmmc", title: "Limit system access to authorized transactions", description: "Limit information system access to the types of transactions and functions that authorized users are permitted to execute.", category: "Access Control", guidance: { learnMore: "Users should only perform actions their role permits. A viewer should not be able to modify resources; a team member should not manage billing.", whyItMatters: "Without transaction-level controls, a compromised low-privilege account can escalate to perform destructive operations.", controlType: "platform", requiredActions: [{ action: "Verify RBAC permission checks on all sensitive routes (automated — system confirms that permission middleware gates every mutation endpoint including creating claws, modifying policies, managing roles, changing settings, and managing teams. Each role (Owner, Admin, Team Member, Viewer) has a defined permission set that limits which transactions it can execute)", configPath: "/app/roles", automated: true }] } },
    { id: "AC.2.007", framework: "cmmc", title: "Employ least privilege", description: "Employ the principle of least privilege, including for specific security functions and privileged accounts.", category: "Access Control", guidance: { learnMore: "Each user should have the minimum level of access needed. Admin privileges should be reserved for those who truly need them.", whyItMatters: "Excessive privileges mean a single compromised account can cause maximum damage across the entire platform.", controlType: "configurable", requiredActions: [{ action: "Review role assignments: Navigate to Roles & Access to audit which users have Admin or Owner roles vs Team Member. Reduce admin count to the minimum needed — most users should be Team Members or Viewers. Options: Owner (full access, limit to 1-2 people), Admin (manage settings and users, limit to essential staff), Team Member (standard day-to-day operations), Viewer (read-only access for auditors and stakeholders).", configPath: "/app/roles", automated: false }, { action: "Enable team-scoped roles: In Teams settings, assign users to specific teams so they only see their team's resources instead of having org-wide access. This ensures each user can only access claws, policies, and data relevant to their team, reducing the blast radius of a compromised account.", configPath: "/app/teams", automated: false }] } },
    { id: "AC.2.008", framework: "cmmc", title: "Control remote access", description: "Control connection and use of remote access to the organization's systems.", category: "Access Control", guidance: { learnMore: "All remote access to the platform (API, dashboard, CLI) must use encrypted channels with strong authentication.", whyItMatters: "Remote access without controls allows attackers to connect from anywhere in the world without detection.", controlType: "platform", requiredActions: [{ action: "Verify TLS encryption on all API connections (automated — system checks that a valid TLS certificate is configured, all HTTP traffic is redirected to HTTPS, and TLS 1.2+ is enforced with no weak cipher suites)", configPath: "/app/settings", automated: true }, { action: "Verify JWT token expiry is configured (automated — system checks globalSettings to confirm access tokens have a maximum lifetime via jwt_expiry_days, and refresh tokens expire appropriately to prevent indefinite session persistence)", configPath: "/app/settings", automated: true }] } },
    { id: "AC.2.016", framework: "cmmc", title: "Control CUI flow", description: "Control the flow of CUI in accordance with approved authorizations.", category: "Access Control", guidance: { learnMore: "Controlled Unclassified Information must only flow through authorized channels. Data classification and OPA policies govern what data goes where.", whyItMatters: "Uncontrolled data flow can lead to CUI being processed by unauthorized AI models or stored in non-compliant regions.", controlType: "configurable", requiredActions: [{ action: "Set data classification on each claw agent: Go to Claw Fleet, click each agent, and set its classification level. Options: 'public' (no restrictions on data flow), 'internal' (org-only access), 'confidential' (need-to-know basis, recommended for most business data), or 'restricted' (CUI/regulated data, triggers strictest controls). Set any agent handling CUI to 'confidential' or 'restricted' so the system enforces appropriate network and access restrictions.", configPath: "/app/claw-fleet?highlight=classification", automated: false }, { action: "Configure network whitelist in OPA policy: Go to Claw Policies, select the policy template assigned to CUI-handling agents, and switch network mode from 'allow-all' to 'whitelist'. Then add only the specific authorized destination domains (e.g., your approved AI model endpoints, internal APIs). Remove any wildcard or overly broad patterns. This prevents CUI from flowing to unauthorized external services.", configPath: "/app/claw-policies?highlight=network-mode", automated: false }] } },
    { id: "AC.3.017", framework: "cmmc", title: "Separate duties of individuals", description: "Separate the duties of individuals to reduce the risk of malevolent activity without collusion.", category: "Access Control", guidance: { learnMore: "No single person should have complete control over critical operations. Separate who can create policies from who can deploy them.", whyItMatters: "Without separation of duties, a rogue insider can both create a malicious configuration and deploy it without oversight.", controlType: "configurable", requiredActions: [{ action: "Create separate roles for different duties: Go to Roles & Access, create custom roles such as 'Policy Author' (can edit claw policies but cannot deploy agents) and 'Deployer' (can deploy agents but cannot edit policies). This ensures no single person controls both policy creation and deployment. Other useful separation patterns: 'Compliance Auditor' (read-only access to audit logs), 'User Manager' (can manage team membership but cannot change roles).", configPath: "/app/roles", automated: false }, { action: "Review that no single user has both policy creation and deployment permissions: In Roles & Access, inspect each Admin and Owner user's assigned permissions. If any user holds both 'manage_policies' and 'deploy_claws' permissions, reassign one of those responsibilities to a different user or role to enforce separation.", configPath: "/app/roles", automated: false }] } },
    { id: "AC.3.021", framework: "cmmc", title: "Authorize remote execution", description: "Authorize remote execution of privileged commands and remote access to security-relevant information.", category: "Access Control", guidance: { learnMore: "Remote commands that change system configuration or access security data must be explicitly authorized and logged.", whyItMatters: "Unauthorized remote commands can disable security controls or exfiltrate audit logs without detection.", controlType: "configurable", requiredActions: [{ action: "Verify admin operations are logged in audit trail (automated — system checks that all role changes, permission modifications, policy updates, and settings changes by admin/owner users generate entries in rbac_audit_events with userId, action, and timestamp)", configPath: "/app/compliance?tab=controls&framework=cmmc&control=AC.3.021", automated: true }, { action: "Enable MFA for admin accounts: Go to Compliance Settings > Authentication & Security, enable 'Require MFA for privileged roles', then select which roles require MFA. At minimum, enforce MFA for Owner and Admin roles. Options: TOTP authenticator app such as Google Authenticator or Authy (recommended — works offline, not vulnerable to SIM-swap), email-based one-time codes (acceptable), or hardware security key via FIDO2/WebAuthn (highest security).", configPath: "/app/compliance-settings?tab=auth-security&highlight=mfa", automated: false }] } },
    { id: "AU.2.041", framework: "cmmc", title: "Ensure audit system accountability", description: "Ensure that the actions of individual system users can be uniquely traced to those users.", category: "Audit & Accountability", guidance: { learnMore: "Every action in the system must be attributable to a specific user via unique identifiers and comprehensive audit logging. Wtrops.ai stamps every audit event with the authenticated user's UUID, ensuring full traceability from action to actor.", whyItMatters: "Without user-level audit trails, investigating incidents becomes impossible and accountability is lost.", controlType: "platform", requiredActions: [{ action: "Verify every user has a unique ID (automated — system checks the users table to confirm all accounts have a distinct UUID and no shared or generic accounts exist)", configPath: "/app/teams", automated: true }, { action: "Verify all API requests log the userId in audit events (automated — system checks that the audit middleware attaches the authenticated userId to every event written to rbac_audit_events, claw_audit_events, and claw_inference_events)", configPath: "/app/compliance?tab=controls&framework=cmmc&control=AU.2.041", automated: true }, { action: "Verify audit log entries include user attribution (automated — system samples recent entries across all audit tables and confirms each has a non-null userId, timestamp, and action field)", configPath: "/app/compliance?tab=controls&framework=cmmc&control=AU.2.041", automated: true }] } },
    { id: "AU.2.042", framework: "cmmc", title: "Create and retain audit logs", description: "Create and retain system audit logs and records to the extent needed.", category: "Audit & Accountability", guidance: { learnMore: "Audit logs must be generated for security-relevant events and retained long enough for investigation. CMMC requires a minimum of 1 year retention for audit records to support incident investigation and compliance audits.", whyItMatters: "Insufficient logging means attacks go undetected. Short retention means evidence is lost before investigations complete.", controlType: "configurable", requiredActions: [{ action: "Configure audit log retention period: Go to Compliance Settings > Data & Retention, set 'Audit Log Retention' to at minimum 365 days. CMMC requires 1 year minimum. Options: 90 days (non-compliant for CMMC), 180 days (non-compliant for CMMC), 365 days (minimum compliant — recommended), 730 days (2 years — for higher assurance), unlimited (keeps all logs indefinitely). Longer retention gives more historical data for incident investigation but uses more storage.", configPath: "/app/compliance-settings?tab=data-retention&highlight=retention-slider", automated: false }, { action: "Verify log storage capacity is sufficient (automated — system checks current audit table sizes, growth rate, and available database storage to confirm the configured retention period can be sustained)", configPath: "/app/compliance?tab=controls&framework=cmmc&control=AU.2.042", automated: true }] } },
    { id: "AU.3.045", framework: "cmmc", title: "Review audit logs", description: "Review and analyze audit logs and take action upon discovering unauthorized activity.", category: "Audit & Accountability", guidance: { learnMore: "Logs must be reviewed regularly (at minimum weekly) and anomalies must trigger investigation and response procedures. Scheduled compliance reports automate the summarization of audit data for human review.", whyItMatters: "Generating logs without reviewing them provides zero security value. Active monitoring turns logs into actionable intelligence.", controlType: "configurable", requiredActions: [{ action: "Configure scheduled compliance reports: Go to Compliance Settings > Scheduled Reports, create a weekly 'Audit Summary' report. Set the recipient to your security team's email distribution list. The report summarizes all RBAC changes, policy violations, failed authentication attempts, and anomalous agent behavior from the past week. Frequency options: daily (high-security environments), weekly (recommended for CMMC), monthly (minimum acceptable).", configPath: "/app/compliance-settings?tab=scheduled-reports", automated: false }, { action: "Designate a log reviewer: In Teams, assign someone the 'Compliance Officer' role who will be responsible for reviewing the weekly audit summary reports and escalating any anomalies. This person should have read access to the compliance dashboard but does not need admin privileges.", configPath: "/app/teams", automated: false }] } },
    { id: "AU.3.048", framework: "cmmc", title: "Collect audit information", description: "Collect audit information into one or more central repositories.", category: "Audit & Accountability", guidance: { learnMore: "All audit data from RBAC events, claw operations, AI inference, tool executions, and data queries flows to five centralized PostgreSQL audit tables: rbac_audit_events, claw_audit_events, claw_inference_events, claw_tool_events, and query_history. All tables share organization_id and UTC timestamps for cross-table correlation.", whyItMatters: "Dispersed logs are difficult to correlate during incident investigation. Centralization enables pattern detection across the platform and satisfies auditor requirements for a single source of truth.", controlType: "platform", requiredActions: [{ action: "Verify all 5 audit tables are receiving events (automated — system queries rbac_audit_events, claw_audit_events, claw_inference_events, claw_tool_events, and query_history for record counts and date ranges to confirm active logging)", configPath: "/app/compliance?tab=controls&framework=cmmc&control=AU.3.048", automated: true }, { action: "Verify cross-table correlation capability (automated — system confirms all tables share organization_id, user-identifying columns, and UTC timestamps enabling unified incident investigation)", configPath: "/app/compliance?tab=controls&framework=cmmc&control=AU.3.048", automated: true }, { action: "Use platform features to generate events across all audit streams: perform RBAC role changes, run Claw agent operations, execute data queries, and invoke tools to populate all 5 tables", configPath: "/app/compliance?tab=controls&framework=cmmc&control=AU.3.048", automated: false }] } },
    { id: "CM.2.061", framework: "cmmc", title: "Establish configuration baselines", description: "Establish and maintain baseline configurations and inventories of organizational systems.", category: "Configuration Management", guidance: { learnMore: "Every system component should have a documented baseline configuration. Wtrops provides 3 system policy templates (Restrictive, Standard, Permissive) that serve as baselines for agent governance. Each claw agent must be assigned to a baseline template so configuration drift can be detected.", whyItMatters: "Without baselines, you cannot detect unauthorized changes or configuration drift. Unmanaged agents operate without policy governance, creating security vulnerabilities.", controlType: "configurable", requiredActions: [{ action: "OPA policy templates serve as configuration baselines (automated — system checks that at least one policy template exists and is available as a baseline configuration for agent governance)", configPath: "/app/claw-policies", automated: true }, { action: "Document which policy template is your baseline: Go to Claw Policies, review the 3 system templates (Restrictive, Standard, Permissive). For CMMC, select 'Standard' or 'Restrictive' as your organization's approved baseline. All new production claws should be assigned this template by default. If you have multiple environments, create separate baseline templates for 'Production' (restrictive) and 'Development' (permissive).", configPath: "/app/claw-policies", automated: false }, { action: "Verify all production claws use the baseline template (automated — system checks each active claw agent's policy assignment and flags any that are not using the designated baseline template or have no template assigned)", configPath: "/app/claw-fleet?highlight=policy-assignment", automated: true }] } },
    { id: "CM.2.062", framework: "cmmc", title: "Employ change control", description: "Track, review, approve, or disapprove, and log changes to organizational systems.", category: "Configuration Management", guidance: { learnMore: "All changes to system configuration (roles, permissions, policies, team membership) are automatically tracked in the RBAC audit trail with full attribution (who, what, when). This provides a tamper-evident change log for compliance audits.", whyItMatters: "Uncontrolled changes are the #1 cause of outages and security incidents. The platform's built-in audit trail automatically captures every configuration change with actor attribution.", controlType: "platform", requiredActions: [{ action: "Verify all configuration changes are logged in RBAC audit trail (automated — system checks audit events for role changes, permission modifications, policy template updates, claw deployments, and settings changes to confirm each has a timestamp, userId, and before/after values)", configPath: "/app/compliance?tab=controls&framework=cmmc&control=CM.2.062", automated: true }, { action: "Verify policy template changes are tracked with timestamps and user attribution (automated — system confirms that every OPA policy template edit generates an audit event recording who made the change, when, and what fields were modified)", configPath: "/app/claw-policies", automated: true }] } },
    { id: "CM.2.064", framework: "cmmc", title: "Employ least functionality", description: "Establish and enforce security configuration settings for IT products employed in organizational systems.", category: "Configuration Management", guidance: { learnMore: "Each claw agent should be configured with only the minimum functionality needed. The Restrictive policy template blocks outbound network access and limits to local AI models. Agents using the Permissive template or allow_all network mode violate this control.", whyItMatters: "Every enabled feature is an attack surface. Agents with unrestricted network access or permissive policies can exfiltrate data or connect to unauthorized services. Least functionality minimizes the blast radius of a compromised agent.", controlType: "configurable", requiredActions: [{ action: "Apply restrictive OPA policy to production claws: Go to Claw Policies, select the 'Restrictive' template for all production agents. This template blocks all outbound network access by default, restricts agents to local AI models only, and requires explicit approval for all tool use. Only add specific network destinations and tools that are required for each agent's function.", configPath: "/app/claw-policies?highlight=network-mode", automated: false }, { action: "Disable unused MCP servers: Go to Settings > Integrations, review the list of active MCP server connections. Deactivate any MCP server integrations that are not actively needed for current operations. Each active integration increases the attack surface and potential data flow paths.", configPath: "/app/settings", automated: false }, { action: "Review installed claw skills: Go to Claw Fleet, for each agent click into its configuration and review the list of installed skills. Remove any skills not required for the agent's specific function. Fewer skills means fewer potential vectors for misuse or exploitation.", configPath: "/app/claw-fleet?highlight=skills-review", automated: false }] } },
    { id: "IA.1.076", framework: "cmmc", title: "Identify system users", description: "Identify information system users, processes acting on behalf of users, or devices.", category: "Identification & Authentication", guidance: { learnMore: "Every entity accessing the system must have a unique identity. No shared accounts. Automated processes must use service accounts with scoped API keys.", whyItMatters: "Shared identities make it impossible to determine who did what during an incident investigation.", controlType: "platform", requiredActions: [{ action: "Verify all users have unique accounts (automated — system checks that every user record has a distinct UUID via gen_random_uuid(), email uniqueness is enforced by database constraint, and no shared or generic accounts like 'admin@company.com' exist)", configPath: "/app/teams", automated: true }, { action: "Verify API keys are scoped to individual service accounts (automated — system checks that each active API key is associated with a specific user or service account and has a defined permission scope, rather than being a shared credential)", configPath: "/app/settings", automated: true }] } },
    { id: "IA.2.078", framework: "cmmc", title: "Enforce password complexity", description: "Enforce a minimum password complexity and change of characters when new passwords are created.", category: "Identification & Authentication", guidance: { learnMore: "Passwords must meet minimum complexity requirements (length, character types) and not be reused from recent history.", whyItMatters: "Weak passwords are trivially cracked via brute force or credential stuffing attacks using leaked password databases.", controlType: "configurable", requiredActions: [{ action: "Configure minimum password length: Go to Compliance Settings > Authentication & Security, set minimum password length to 12 or higher. CMMC recommends 12+ characters. Options: 8 (minimum, not recommended), 10, 12 (recommended for CMMC), 14, 16 (high security). Longer passwords are exponentially harder to crack — each additional character multiplies the search space by ~95x.", configPath: "/app/compliance-settings?tab=auth-security&highlight=password-policy", automated: false }, { action: "Enable password history: Prevents users from reusing recent passwords. This is configured at the platform level.", configPath: "/app/compliance-settings?tab=auth-security&highlight=password-policy", automated: false }] } },
    { id: "IA.2.081", framework: "cmmc", title: "Multi-factor authentication", description: "Use multi-factor authentication for local and network access to privileged accounts.", category: "Identification & Authentication", guidance: { learnMore: "Admin and Owner accounts must use MFA (TOTP authenticator app). MFA should be available for all users and enforced for privileged roles.", whyItMatters: "MFA blocks 99.9% of automated credential attacks. Without it, a stolen password gives full account access.", controlType: "configurable", requiredActions: [{ action: "Enable MFA requirement for privileged roles: Go to Compliance Settings > Authentication & Security, toggle 'Require MFA' to ON, then select which roles must use MFA. For CMMC Level 2, at minimum Owner and Admin roles must have MFA. Options for MFA enforcement: Owner only (minimum), Owner + Admin (recommended for CMMC), All roles (maximum security).", configPath: "/app/compliance-settings?tab=auth-security&highlight=mfa", automated: false }, { action: "Enroll in MFA: Each user with a required role must set up their TOTP authenticator. Go to account settings to scan the QR code with an authenticator app (Google Authenticator, Authy, 1Password). After scanning, enter the 6-digit code to verify.", configPath: "/app/compliance-settings?tab=auth-security&highlight=mfa", automated: false }, { action: "Monitor MFA adoption: The compliance dashboard shows what percentage of required users have enrolled. 100% enrollment is required for this control to pass.", configPath: "/app/compliance?tab=controls&framework=cmmc&control=IA.2.081", automated: false }] } },
    { id: "IR.2.092", framework: "cmmc", title: "Establish incident response capability", description: "Establish an operational incident-handling capability for organizational systems.", category: "Incident Response", guidance: { learnMore: "The organization must have documented procedures for detecting, reporting, and responding to security incidents. This includes designated IR contacts, a written IR plan covering all 6 phases (preparation, identification, containment, eradication, recovery, lessons learned), and a designated IR team with defined roles.", whyItMatters: "Without an incident response plan, teams panic during breaches, causing delayed response and increased damage. CMMC requires a documented, tested IR capability — not just good intentions.", controlType: "configurable", requiredActions: [{ action: "Configure incident response contacts: Go to Compliance Settings > Incident Response. Set up: Primary IR Contact (the first person called during an incident — typically your security lead or CTO), Secondary Contact (backup if primary is unavailable), Escalation Email (a group email like security@company.com that reaches the whole IR team), Slack Webhook (optional — for instant notification in your Slack channel when an incident is detected).", configPath: "/app/compliance-settings?tab=incident-response&highlight=ir-contacts", automated: false }, { action: "Document your IR plan: An incident response plan must cover 6 phases: 1) Preparation (team, tools, training), 2) Identification (how incidents are detected), 3) Containment (immediate actions to limit damage), 4) Eradication (remove the threat), 5) Recovery (restore normal operations), 6) Lessons Learned (post-incident review). Upload your IR plan document in the evidence section below.", configPath: "/app/compliance?tab=controls&framework=cmmc&control=IR.2.092&action=add-evidence", automated: false }, { action: "Designate IR team members: Go to Teams, create an 'Incident Response' team. Add your IR lead, security engineers, and communications contact. Each person should know their role during an incident.", configPath: "/app/teams", automated: false }, { action: "Test your IR plan annually: CMMC requires testing. Document your last IR drill or tabletop exercise. If you haven't done one, schedule one — even a 2-hour tabletop exercise counts.", configPath: "/app/compliance?tab=controls&framework=cmmc&control=IR.2.092&action=add-evidence", automated: false }] } },
    { id: "IR.2.093", framework: "cmmc", title: "Detect and report events", description: "Detect and report events consistent with established incident response procedures.", category: "Incident Response", guidance: { learnMore: "Security events must be detected through monitoring, reported through defined channels, and documented in the audit trail. The platform automatically captures claw lifecycle events, policy violations, access denials, and configuration changes. Configurable reporting ensures these events are regularly reviewed.", whyItMatters: "Undetected events fester into full breaches. The average undetected breach persists for 200+ days. Active detection and regular reporting are the difference between a contained incident and a catastrophic breach.", controlType: "configurable", requiredActions: [{ action: "Verify the compliance dashboard surfaces security events (automated — system checks that OPA policy violations, failed authentication attempts, unauthorized access attempts, and anomalous agent behavior are captured in audit tables and displayed in the compliance dashboard)", configPath: "/app/compliance?tab=controls&framework=cmmc&control=IR.2.093", automated: true }, { action: "Configure OPA policy violation alerting: Go to Claw Policies > Alert Settings, enable notifications for policy violations. Set notification channels — options: email to security team, webhook to your incident management tool (PagerDuty, Opsgenie), or Slack channel. Set severity thresholds: alert immediately on 'block' actions, send daily digest for 'warn' actions.", configPath: "/app/claw-policies", automated: false }, { action: "Establish event reporting channels: Document how team members should report suspected security events. Create a dedicated email alias (e.g., security@yourorg.com) and document the escalation path in your incident response procedures. Upload the reporting guide to Compliance Settings > Documents.", configPath: "/app/compliance?tab=controls&framework=cmmc&control=IR.2.093&action=add-evidence", automated: false }] } },
    { id: "SC.1.175", framework: "cmmc", title: "Monitor communications at boundaries", description: "Monitor, control, and protect organizational communications at external boundaries.", category: "System & Communications Protection", guidance: { learnMore: "All network traffic at system boundaries must be monitored and controlled. OPA network policies enforce what external services claws can reach.", whyItMatters: "Unmonitored boundaries allow data exfiltration, command-and-control communications, and lateral movement.", controlType: "configurable", requiredActions: [{ action: "Configure OPA network whitelist policies: Go to Claw Policies, edit the active policy template, and define allowed outbound destinations under 'Network Rules'. Options: 'deny-all' (block all outbound — most secure, suitable for agents that only process local data), 'allow-list' (only specified domains — recommended for production), or 'deny-list' (block specific domains — least secure). For CUI-handling agents, use 'allow-list' mode and add only the specific domains required.", configPath: "/app/claw-policies?highlight=network-mode", automated: false }, { action: "Verify network request logging for all claw agents (automated — system confirms that every outbound HTTP request made by any claw agent is logged in claw_tool_events with destination URL, response code, requesting agent ID, and timestamp)", configPath: "/app/claw-fleet", automated: true }] } },
    { id: "SC.1.176", framework: "cmmc", title: "Implement subnetwork separation", description: "Implement subnetworks for publicly accessible system components that are physically or logically separated.", category: "System & Communications Protection", guidance: { learnMore: "Public-facing components must be isolated from internal systems. Claw sandboxes run in isolated containers with no direct database access.", whyItMatters: "Without network segmentation, a compromised public-facing component gives direct access to internal databases and services.", controlType: "platform", requiredActions: [{ action: "Verify claw sandboxes run in isolated environments (automated — system checks that each active claw agent is assigned to a sandboxed container with its own network namespace, no direct database connection strings, and defined CPU/memory resource limits)", configPath: "/app/claw-fleet?highlight=sandbox", automated: true }, { action: "Verify sandbox network isolation configuration (automated — system confirms that OPA network policies are evaluated on every outbound request from sandboxed agents, and that agents cannot communicate directly with each other or with the platform's internal services without going through the authorized API gateway)", configPath: "/app/claw-policies", automated: true }] } },
    { id: "SC.3.177", framework: "cmmc", title: "Employ cryptographic mechanisms", description: "Employ FIPS-validated cryptography when used to protect the confidentiality of CUI.", category: "System & Communications Protection", guidance: { learnMore: "All data containing CUI must be encrypted using validated cryptographic standards both at rest (AES-256) and in transit (TLS 1.2+).", whyItMatters: "Unencrypted CUI can be intercepted in transit or extracted from storage by any attacker with access to the infrastructure.", controlType: "platform", requiredActions: [{ action: "Verify TLS is enforced on all API endpoints (automated — system checks that the server's TLS certificate is valid, TLS 1.2 or higher is required, and weak cipher suites are disabled)", configPath: "/app/settings", automated: true }, { action: "Verify database connections use SSL (automated — system checks that all database connection strings include sslmode=require or sslmode=verify-full, ensuring data in transit between the application and database is encrypted)", configPath: "/app/settings", automated: true }, { action: "Document encryption standards: Upload your organization's encryption policy to Compliance Settings > Documents. The document should specify: AES-256 for data at rest, TLS 1.2+ for data in transit, key management procedures, and key rotation schedule. This provides auditors with evidence of your cryptographic controls.", configPath: "/app/compliance?tab=controls&framework=cmmc&control=SC.3.177&action=add-evidence", automated: false }] } },
    { id: "SC.3.187", framework: "cmmc", title: "Protect authenticity of communications", description: "Protect the authenticity of communications sessions.", category: "System & Communications Protection", guidance: { learnMore: "Communication sessions must use authenticated and encrypted channels. JWT tokens, HMAC-signed messages, and TLS prevent session hijacking.", whyItMatters: "Session hijacking allows attackers to impersonate legitimate users and perform actions on their behalf.", controlType: "platform", requiredActions: [{ action: "Verify JWT-based session management (automated — system confirms that all authenticated API sessions use signed JWT tokens with expiration, that tokens are validated on every request, and that expired or malformed tokens are rejected)", configPath: "/app/settings", automated: true }, { action: "Verify HMAC signing on claw-manager Redis streams (automated — system checks that messages between the platform and claw-manager use HMAC signatures to prevent message tampering, and that unsigned or incorrectly signed messages are rejected)", configPath: "/app/claw-fleet", automated: true }] } },
    { id: "SI.1.210", framework: "cmmc", title: "Identify and remediate flaws", description: "Identify, report, and correct information and information system flaws in a timely manner.", category: "System & Information Integrity", guidance: { learnMore: "Software vulnerabilities must be identified through scanning, reported, and patched within defined timeframes based on severity.", whyItMatters: "Unpatched vulnerabilities are the entry point for most cyberattacks. Timely patching closes known attack vectors.", controlType: "evidence", requiredActions: [{ action: "Document vulnerability management procedures: Create a Vulnerability Management Policy covering: (1) scanning frequency — at minimum monthly automated scans plus ad-hoc scans after major changes, (2) severity-based remediation SLAs — Critical within 48 hours, High within 7 days, Medium within 30 days, Low within 90 days, (3) responsible parties for triage, remediation, and verification. Upload to Compliance Settings > Documents.", configPath: "/app/compliance?tab=controls&framework=cmmc&control=SI.1.210&action=add-evidence", automated: false }, { action: "Document patch management procedures: Create a Patch Management Policy covering: (1) patch evaluation process, (2) testing requirements before production deployment, (3) emergency patching procedures for zero-day vulnerabilities, (4) rollback procedures if a patch causes issues. Upload to Compliance Settings > Documents.", configPath: "/app/compliance?tab=controls&framework=cmmc&control=SI.1.210&action=add-evidence", automated: false }, { action: "Enable dependency vulnerability scanning: Configure automated dependency scanning (e.g., npm audit, Snyk, or Dependabot) in your CI/CD pipeline to run on every build. Document the scanning tool and its configuration in your vulnerability management procedures.", configPath: "/app/compliance?tab=controls&framework=cmmc&control=SI.1.210&action=add-evidence", automated: false }] } },
    { id: "SI.1.211", framework: "cmmc", title: "Provide protection from malicious code", description: "Provide protection from malicious code at appropriate locations within organizational systems.", category: "System & Information Integrity", guidance: { learnMore: "Claw agents running in sandboxes are isolated from the host system. OPA policies restrict what skills and tools they can use, preventing malicious code execution. Skill security scoring blocks skills below a minimum security grade.", whyItMatters: "Malicious code can steal data, destroy systems, or establish persistent access for attackers. Skill security scoring is the first line of defense against untrusted code.", controlType: "platform", requiredActions: [{ action: "Verify skill security scoring is active for all claw agents (automated — system checks that every claw agent has skill security scoring enabled, which evaluates each installed skill's risk level based on its requested permissions, network access, and code provenance)", configPath: "/app/claw-policies?highlight=skill-security", automated: true }, { action: "Verify OPA policy blocks untrusted skills (automated — system confirms that the active OPA policy template includes a rule to block skills with a security score below the configured threshold, and that skills from unverified sources are denied by default)", configPath: "/app/claw-policies?highlight=skill-security", automated: true }] } },
    { id: "SI.2.214", framework: "cmmc", title: "Monitor system security alerts", description: "Monitor system security alerts and advisories and take appropriate actions in response.", category: "System & Information Integrity", guidance: { learnMore: "Security alerts from monitoring, OPA policy violations, and compliance checks must be reviewed and acted upon. The platform monitors claw audit events, inference events, and tool events across all agents.", whyItMatters: "Ignoring security alerts defeats the purpose of monitoring. Each unaddressed alert is a potential breach in progress.", controlType: "configurable", requiredActions: [{ action: "Verify OPA policy violations appear in compliance dashboard (automated — system confirms that policy violation events from all claw agents are written to the audit tables and surfaced in the compliance dashboard with severity, agent ID, violated rule, and timestamp)", configPath: "/app/compliance?tab=controls&framework=cmmc&control=SI.2.214", automated: true }, { action: "Establish a security alert review cadence: Go to Compliance Settings > Scheduled Reports, configure a daily 'Security Alerts' report that summarizes all policy violations, failed authentication attempts, and anomalous events from the past 24 hours. Assign a specific team member to review this report each business day and document any actions taken.", configPath: "/app/compliance-settings?tab=scheduled-reports", automated: false }, { action: "Configure alert escalation thresholds: Go to Claw Policies > Alert Settings, define thresholds that trigger immediate escalation. Recommended: more than 5 policy violations from a single agent in 1 hour (possible compromise), more than 10 failed auth attempts for a single user in 15 minutes (possible brute force), any 'restricted' classified data access outside business hours (possible insider threat).", configPath: "/app/claw-policies", automated: false }] } },
  ];
}

// ════════════════════════════════════════════════════════════════════════════════
// HIPAA — Health Insurance Portability and Accountability Act
// ════════════════════════════════════════════════════════════════════════════════

export function getHipaaControls(): ControlDef[] {
  return [
    { id: "164.308.a.1", framework: "hipaa", title: "Security Management Process", description: "Implement policies and procedures to prevent, detect, contain, and correct security violations.", category: "Administrative Safeguards", guidance: { learnMore: "Organizations handling PHI must have a comprehensive security management process including risk analysis, risk management, sanction policy, and information system activity review.", whyItMatters: "HIPAA violations can result in fines from $100 to $50,000 per violation, with annual maximums of $1.5M per category.", requiredActions: [{ action: "Document security management policies", configPath: "/app/compliance", automated: false }, { action: "Conduct risk analysis of PHI handling", configPath: "/app/compliance", automated: false }, { action: "Configure audit logging for all PHI access", configPath: "/app/compliance", automated: true }] } },
    { id: "164.308.a.2", framework: "hipaa", title: "Assigned Security Responsibility", description: "Identify the security official responsible for developing and implementing security policies.", category: "Administrative Safeguards", guidance: { learnMore: "A specific individual must be designated as the security official responsible for HIPAA security compliance.", whyItMatters: "Without clear ownership, security responsibilities fall through the cracks and nobody is accountable.", requiredActions: [{ action: "Assign a security officer role in the organization", configPath: "/app/teams", automated: false }, { action: "Create a Compliance Officer custom role", configPath: "/app/roles", automated: false }] } },
    { id: "164.308.a.3", framework: "hipaa", title: "Workforce Security", description: "Implement policies and procedures to ensure workforce members have appropriate access to ePHI.", category: "Administrative Safeguards", guidance: { learnMore: "Access to PHI must be based on role-based authorization. Workforce members should only access the minimum PHI needed for their job function.", whyItMatters: "Unauthorized PHI access is a reportable breach. Each employee with unnecessary access multiplies breach risk.", requiredActions: [{ action: "Configure team-based access scoping", configPath: "/app/teams", automated: true }, { action: "Implement least-privilege RBAC roles", configPath: "/app/roles", automated: true }, { action: "Set up access termination procedures", configPath: "/app/roles", automated: false }] } },
    { id: "164.308.a.4", framework: "hipaa", title: "Information Access Management", description: "Implement policies and procedures for authorizing access to ePHI.", category: "Administrative Safeguards", guidance: { learnMore: "Access to PHI systems must be formally authorized, documented, and periodically reviewed. Access must be revoked when no longer needed.", whyItMatters: "Stale access permissions accumulate over time. Former employees or role changes leave unnecessary PHI access in place.", requiredActions: [{ action: "Review and document access authorization procedures", configPath: "/app/compliance", automated: false }, { action: "Conduct quarterly access reviews", configPath: "/app/roles", automated: false }, { action: "Enable RBAC audit trail for access changes", configPath: "/app/compliance", automated: true }] } },
    { id: "164.308.a.5", framework: "hipaa", title: "Security Awareness and Training", description: "Implement a security awareness and training program for all workforce members.", category: "Administrative Safeguards", guidance: { learnMore: "All personnel who handle PHI must receive security awareness training covering password management, malware protection, and incident reporting.", whyItMatters: "Human error causes over 80% of healthcare breaches. Training is the most cost-effective security control.", requiredActions: [{ action: "Document security training program", configPath: "/app/compliance", automated: false }, { action: "Track training completion for team members", configPath: "/app/teams", automated: false }] } },
    { id: "164.308.a.6", framework: "hipaa", title: "Security Incident Procedures", description: "Implement policies and procedures to address security incidents.", category: "Administrative Safeguards", guidance: { learnMore: "The organization must have procedures to identify, respond to, mitigate, and document security incidents involving PHI.", whyItMatters: "HIPAA requires breach notification within 60 days. Without incident procedures, this deadline is easily missed.", requiredActions: [{ action: "Document incident response procedures for PHI breaches", configPath: "/app/compliance", automated: false }, { action: "Configure security event monitoring", configPath: "/app/compliance", automated: true }] } },
    { id: "164.308.a.7", framework: "hipaa", title: "Contingency Plan", description: "Establish policies and procedures for responding to an emergency that damages systems containing ePHI.", category: "Administrative Safeguards", guidance: { learnMore: "A contingency plan must include data backup, disaster recovery, and emergency mode operation procedures.", whyItMatters: "Without a contingency plan, a system failure can result in permanent loss of PHI and inability to provide care.", requiredActions: [{ action: "Document data backup and recovery procedures", configPath: "/app/compliance", automated: false }, { action: "Verify database backup configuration", configPath: "/app/settings", automated: true }, { action: "Test recovery procedures annually", configPath: "/app/compliance", automated: false }] } },
    { id: "164.312.a.1", framework: "hipaa", title: "Access Control", description: "Implement technical policies and procedures for systems that maintain ePHI to allow access only to authorized persons.", category: "Technical Safeguards", guidance: { learnMore: "Technical access controls must include unique user identification, emergency access procedures, automatic logoff, and encryption.", whyItMatters: "Technical controls are the last line of defense. Even with policies, technical enforcement prevents unauthorized access.", requiredActions: [{ action: "Verify unique user IDs are enforced", configPath: "/app/teams", automated: true }, { action: "Configure session timeout", configPath: "/app/settings", automated: false }, { action: "Enable data encryption at rest and in transit", configPath: "/app/settings", automated: true }] } },
    { id: "164.312.b", framework: "hipaa", title: "Audit Controls", description: "Implement hardware, software, and/or procedural mechanisms that record and examine activity in systems containing ePHI.", category: "Technical Safeguards", guidance: { learnMore: "Comprehensive audit logs must capture who accessed what PHI, when, and what they did with it.", whyItMatters: "Audit controls are required for both compliance verification and breach investigation. Without them, breaches cannot be properly assessed.", requiredActions: [{ action: "Verify comprehensive audit logging is enabled", configPath: "/app/compliance", automated: true }, { action: "Configure audit log review procedures", configPath: "/app/compliance", automated: false }] } },
    { id: "164.312.c.1", framework: "hipaa", title: "Integrity Controls", description: "Implement policies and procedures to protect ePHI from improper alteration or destruction.", category: "Technical Safeguards", guidance: { learnMore: "Technical mechanisms must ensure PHI is not altered or destroyed without authorization. This includes checksums, access controls, and backup verification.", whyItMatters: "Corrupted or improperly modified PHI can lead to incorrect medical decisions with life-threatening consequences.", requiredActions: [{ action: "Implement database integrity checks", configPath: "/app/settings", automated: true }, { action: "Verify audit trails are append-only and tamper-evident", configPath: "/app/compliance", automated: true }] } },
    { id: "164.312.d", framework: "hipaa", title: "Person or Entity Authentication", description: "Implement procedures to verify that a person or entity seeking access to ePHI is the one claimed.", category: "Technical Safeguards", guidance: { learnMore: "Strong authentication mechanisms must verify user identity before granting access to PHI systems.", whyItMatters: "Weak authentication allows impersonation attacks. Healthcare records are worth 10x more than credit cards on the dark web.", requiredActions: [{ action: "Enforce strong authentication (JWT + refresh tokens)", configPath: "/app/settings", automated: true }, { action: "Enable MFA for users with PHI access", configPath: "/app/settings", automated: false }] } },
    { id: "164.312.e.1", framework: "hipaa", title: "Transmission Security", description: "Implement technical security measures to guard against unauthorized access to ePHI being transmitted over a network.", category: "Technical Safeguards", guidance: { learnMore: "All PHI transmitted over networks must be encrypted using TLS 1.2 or higher. This applies to API calls, database connections, and inter-service communication.", whyItMatters: "Unencrypted PHI in transit can be intercepted by anyone with network access, including on public Wi-Fi or compromised infrastructure.", requiredActions: [{ action: "Verify TLS is enforced on all connections", configPath: "/app/settings", automated: true }, { action: "Verify database connections use SSL", configPath: "/app/settings", automated: true }] } },
    { id: "164.310.a.1", framework: "hipaa", title: "Facility Access Controls", description: "Implement policies and procedures to limit physical access to electronic information systems.", category: "Physical Safeguards", guidance: { learnMore: "Physical access to systems containing PHI must be restricted to authorized personnel. Cloud deployments inherit physical security from the cloud provider.", whyItMatters: "Physical access bypasses all software controls. An attacker with physical access can extract data directly from storage.", requiredActions: [{ action: "Document cloud provider physical security certifications", configPath: "/app/compliance", automated: false }, { action: "Verify OCI data center security compliance", configPath: "/app/compliance", automated: false }] } },
    { id: "164.310.d.1", framework: "hipaa", title: "Device and Media Controls", description: "Implement policies governing the receipt and removal of hardware and electronic media containing ePHI.", category: "Physical Safeguards", guidance: { learnMore: "Controls must exist for disposal, media re-use, accountability, and data backup and storage of devices containing PHI.", whyItMatters: "Improper disposal of devices containing PHI is a common source of breaches. A single lost laptop can expose thousands of records.", requiredActions: [{ action: "Document media disposal procedures", configPath: "/app/compliance", automated: false }, { action: "Ensure data encryption at rest covers all storage", configPath: "/app/settings", automated: true }] } },
    { id: "164.404.a", framework: "hipaa", title: "Breach Notification to Individuals", description: "Notify affected individuals following the discovery of a breach of unsecured PHI.", category: "Breach Notification", guidance: { learnMore: "Individuals must be notified within 60 days of discovering a breach. Notification must include description, types of information, steps to protect themselves, and contact information.", whyItMatters: "Failure to notify within 60 days results in additional penalties. Affected individuals have a right to know their data was compromised.", requiredActions: [{ action: "Document breach notification procedures and templates", configPath: "/app/compliance", automated: false }, { action: "Configure security event detection for breach indicators", configPath: "/app/compliance", automated: true }] } },
    { id: "164.404.d", framework: "hipaa", title: "Breach Documentation", description: "Maintain documentation of breach notifications and retain for 6 years.", category: "Breach Notification", guidance: { learnMore: "All breach investigations, risk assessments, and notifications must be documented and retained for at minimum 6 years.", whyItMatters: "HHS may audit breach records years after an incident. Missing documentation leads to presumption of non-compliance.", requiredActions: [{ action: "Configure audit log retention to 6+ years for PHI systems", configPath: "/app/compliance", automated: false }, { action: "Document breach response activities in compliance records", configPath: "/app/compliance", automated: false }] } },
  ];
}

// ════════════════════════════════════════════════════════════════════════════════
// GDPR — EU General Data Protection Regulation
// ════════════════════════════════════════════════════════════════════════════════

export function getGdprControls(): ControlDef[] {
  return [
    { id: "GDPR.5.1", framework: "gdpr", title: "Lawfulness, Fairness, Transparency", description: "Personal data shall be processed lawfully, fairly and in a transparent manner (Article 5.1a).", category: "Principles", guidance: { learnMore: "All processing of personal data must have a lawful basis (consent, contract, legal obligation, vital interests, public task, or legitimate interests). Processing must be transparent to data subjects.", whyItMatters: "Processing without a lawful basis is automatically a GDPR violation with fines up to 4% of annual global revenue or €20M.", requiredActions: [{ action: "Document lawful basis for each type of data processing", configPath: "/app/compliance", automated: false }, { action: "Publish a clear privacy notice", configPath: "/app/compliance", automated: false }] } },
    { id: "GDPR.5.1b", framework: "gdpr", title: "Purpose Limitation", description: "Personal data shall be collected for specified, explicit and legitimate purposes (Article 5.1b).", category: "Principles", guidance: { learnMore: "Data collected for one purpose cannot be used for incompatible purposes without additional consent or legal basis.", whyItMatters: "Using customer data collected for service delivery for marketing without consent is a common and costly GDPR violation.", requiredActions: [{ action: "Document purposes for each data processing activity", configPath: "/app/compliance", automated: false }, { action: "Configure data classification labels on resources", configPath: "/app/claw-fleet", automated: false }] } },
    { id: "GDPR.5.1c", framework: "gdpr", title: "Data Minimization", description: "Personal data shall be adequate, relevant and limited to what is necessary (Article 5.1c).", category: "Principles", guidance: { learnMore: "Only collect and process the minimum personal data needed for the stated purpose. Do not collect data speculatively.", whyItMatters: "Excessive data collection increases breach impact and storage costs while providing no business value.", requiredActions: [{ action: "Review data fields collected and remove unnecessary ones", configPath: "/app/compliance", automated: false }, { action: "Configure Copilot query restrictions to minimize data access", configPath: "/app/copilot", automated: false }] } },
    { id: "GDPR.6", framework: "gdpr", title: "Consent Management", description: "Where consent is the lawful basis, it must be freely given, specific, informed and unambiguous (Article 6-7).", category: "Consent", guidance: { learnMore: "Consent must be a clear affirmative act. Pre-ticked boxes are not valid consent. Consent must be as easy to withdraw as to give.", whyItMatters: "Invalid consent means all processing based on it is unlawful. This can invalidate entire data processing operations retroactively.", requiredActions: [{ action: "Implement granular consent management in user settings", configPath: "/app/settings", automated: false }, { action: "Ensure consent records are stored with timestamps", configPath: "/app/compliance", automated: true }] } },
    { id: "GDPR.15", framework: "gdpr", title: "Right of Access", description: "Data subjects have the right to obtain confirmation of processing and access to their personal data (Article 15).", category: "Data Subject Rights", guidance: { learnMore: "Upon request, you must provide a copy of all personal data being processed, the purposes, categories, recipients, and retention periods within 30 days.", whyItMatters: "Failure to respond to a Subject Access Request within 30 days is a violation. Automated systems make this efficient.", requiredActions: [{ action: "Implement data export functionality for user data", configPath: "/app/settings", automated: false }, { action: "Document SAR response procedures", configPath: "/app/compliance", automated: false }] } },
    { id: "GDPR.16", framework: "gdpr", title: "Right to Rectification", description: "Data subjects have the right to obtain rectification of inaccurate personal data (Article 16).", category: "Data Subject Rights", guidance: { learnMore: "Inaccurate personal data must be corrected without undue delay upon request. Incomplete data must be completed.", whyItMatters: "Inaccurate data can lead to wrong decisions about individuals, causing both harm and legal liability.", requiredActions: [{ action: "Ensure users can edit their profile information", configPath: "/app/settings", automated: true }, { action: "Document data correction procedures", configPath: "/app/compliance", automated: false }] } },
    { id: "GDPR.17", framework: "gdpr", title: "Right to Erasure", description: "Data subjects have the right to erasure of their personal data (right to be forgotten) (Article 17).", category: "Data Subject Rights", guidance: { learnMore: "Personal data must be erased when no longer necessary, consent is withdrawn, processing is unlawful, or a legal obligation requires it.", whyItMatters: "The right to be forgotten is heavily enforced. Organizations must be able to locate and delete all personal data for an individual.", requiredActions: [{ action: "Implement account deletion functionality", configPath: "/app/settings", automated: true }, { action: "Verify data is purged from all systems including backups", configPath: "/app/compliance", automated: false }] } },
    { id: "GDPR.20", framework: "gdpr", title: "Right to Data Portability", description: "Data subjects have the right to receive their data in a structured, machine-readable format (Article 20).", category: "Data Subject Rights", guidance: { learnMore: "When processing is based on consent or contract and carried out by automated means, data must be provided in a common, machine-readable format.", whyItMatters: "Data portability promotes competition and gives individuals control. It applies to all data the individual provided, including derived data.", requiredActions: [{ action: "Implement JSON/CSV data export for user data", configPath: "/app/settings", automated: false }, { action: "Document data portability procedures", configPath: "/app/compliance", automated: false }] } },
    { id: "GDPR.25", framework: "gdpr", title: "Data Protection by Design and Default", description: "Implement appropriate technical and organizational measures for data protection (Article 25).", category: "Controller Obligations", guidance: { learnMore: "Privacy must be built into system design, not bolted on. Default settings must be the most privacy-protective. Only necessary data should be processed by default.", whyItMatters: "DPbD is both a legal requirement and a competitive advantage. Privacy-first design prevents breaches by eliminating unnecessary data exposure.", requiredActions: [{ action: "Configure OPA policies with restrictive defaults", configPath: "/app/claw-policies", automated: true }, { action: "Review data classification and minimize data retention", configPath: "/app/compliance", automated: false }, { action: "Enable team-scoped access as default", configPath: "/app/teams", automated: false }] } },
    { id: "GDPR.28", framework: "gdpr", title: "Processor Obligations", description: "Processing by a processor shall be governed by a contract setting out the subject-matter and duration (Article 28).", category: "Controller Obligations", guidance: { learnMore: "All third-party processors must have Data Processing Agreements (DPAs) specifying processing scope, security requirements, and breach notification procedures.", whyItMatters: "Controllers are liable for processor violations. Without a DPA, the controller has no legal recourse and faces direct regulatory action.", requiredActions: [{ action: "Document DPAs with all third-party service providers", configPath: "/app/compliance", automated: false }, { action: "Review telephony provider data handling practices", configPath: "/app/telephony", automated: false }] } },
    { id: "GDPR.30", framework: "gdpr", title: "Records of Processing Activities", description: "Maintain a record of processing activities under its responsibility (Article 30).", category: "Controller Obligations", guidance: { learnMore: "Organizations must maintain documented records of all processing activities including purposes, data categories, recipients, transfers, and retention periods.", whyItMatters: "Records of processing are the first thing regulators request during an investigation. Missing records create a presumption of non-compliance.", requiredActions: [{ action: "Maintain processing activity records in compliance documentation", configPath: "/app/compliance", automated: false }, { action: "Enable audit logging for all data processing activities", configPath: "/app/compliance", automated: true }] } },
    { id: "GDPR.32", framework: "gdpr", title: "Security of Processing", description: "Implement appropriate technical and organizational measures to ensure security (Article 32).", category: "Controller Obligations", guidance: { learnMore: "Security measures must include encryption, confidentiality/integrity/availability, resilience, and regular testing. Measures must be appropriate to the risk level.", whyItMatters: "A security breach affecting personal data triggers mandatory 72-hour notification to regulators and potential fines.", requiredActions: [{ action: "Verify encryption at rest and in transit", configPath: "/app/settings", automated: true }, { action: "Configure OPA policies for data access control", configPath: "/app/claw-policies", automated: true }, { action: "Implement RBAC with least-privilege principle", configPath: "/app/roles", automated: true }] } },
    { id: "GDPR.33", framework: "gdpr", title: "Breach Notification to Supervisory Authority", description: "Notify the supervisory authority within 72 hours of becoming aware of a personal data breach (Article 33).", category: "Controller Obligations", guidance: { learnMore: "Breaches likely to result in risk to individuals must be reported to the DPA within 72 hours. The notification must include nature, categories, consequences, and measures taken.", whyItMatters: "Late notification is itself a violation. The 72-hour clock starts from awareness, not discovery. Automated detection accelerates this.", requiredActions: [{ action: "Configure breach detection monitoring", configPath: "/app/compliance", automated: true }, { action: "Document 72-hour breach notification procedures", configPath: "/app/compliance", automated: false }, { action: "Prepare breach notification templates", configPath: "/app/compliance", automated: false }] } },
    { id: "GDPR.35", framework: "gdpr", title: "Data Protection Impact Assessment", description: "Carry out a DPIA where processing is likely to result in high risk (Article 35).", category: "Controller Obligations", guidance: { learnMore: "A DPIA is required for systematic processing of sensitive data, large-scale monitoring, or automated decision-making with legal effects.", whyItMatters: "AI-powered voice agents processing personal conversations are high-risk by nature. A DPIA is almost certainly required.", requiredActions: [{ action: "Conduct and document DPIA for AI agent processing", configPath: "/app/compliance", automated: false }, { action: "Review AI model data handling practices", configPath: "/app/claw-fleet", automated: false }] } },
    { id: "GDPR.37", framework: "gdpr", title: "Data Protection Officer", description: "Designate a Data Protection Officer where required (Article 37-39).", category: "DPO & Governance", guidance: { learnMore: "A DPO must be designated when core activities involve regular and systematic monitoring of individuals at scale or processing special categories of data at scale.", whyItMatters: "Operating without a required DPO is itself a violation. The DPO provides expert guidance and acts as the regulator contact point.", requiredActions: [{ action: "Assess whether a DPO is required for your processing activities", configPath: "/app/compliance", automated: false }, { action: "Designate a DPO or document why one is not required", configPath: "/app/teams", automated: false }] } },
    { id: "GDPR.44", framework: "gdpr", title: "International Data Transfers", description: "Transfer of personal data to third countries subject to appropriate safeguards (Articles 44-49).", category: "International Transfers", guidance: { learnMore: "Personal data can only be transferred outside the EU/EEA to countries with adequacy decisions, or with appropriate safeguards like Standard Contractual Clauses.", whyItMatters: "International transfers without safeguards violate GDPR. The Schrems II decision invalidated Privacy Shield, increasing transfer complexity.", requiredActions: [{ action: "Configure data residency region to EU for EU customers", configPath: "/app/settings", automated: false }, { action: "Document transfer mechanisms for any non-EU processing", configPath: "/app/compliance", automated: false }, { action: "Review deployment regions for data residency compliance", configPath: "/app/compliance", automated: true }] } },
  ];
}

// ════════════════════════════════════════════════════════════════════════════════
// PCI DSS v4.0 — Payment Card Industry Data Security Standard
// ════════════════════════════════════════════════════════════════════════════════

export function getPciDssControls(): ControlDef[] {
  return [
    { id: "PCI.1.1", framework: "pci_dss", title: "Install and Maintain Network Security Controls", description: "Network security controls are defined and implemented to protect cardholder data.", category: "Network Security", guidance: { learnMore: "Firewalls, network segmentation, and access control lists must protect all systems that store, process, or transmit cardholder data.", whyItMatters: "The network perimeter is the first line of defense. Weak network controls expose cardholder data to external attackers.", requiredActions: [{ action: "Configure OPA network policies for payment-handling agents", configPath: "/app/claw-policies", automated: true }, { action: "Document network architecture and data flow diagrams", configPath: "/app/compliance", automated: false }] } },
    { id: "PCI.2.1", framework: "pci_dss", title: "Apply Secure Configurations", description: "Apply secure configurations to all system components to reduce vulnerabilities.", category: "Network Security", guidance: { learnMore: "Default passwords, unnecessary services, and insecure protocols must be eliminated. All components must be hardened to security baselines.", whyItMatters: "Default configurations are the first thing attackers try. A single unpatched default credential can compromise an entire payment system.", requiredActions: [{ action: "Review and harden all system default configurations", configPath: "/app/settings", automated: false }, { action: "Use restrictive OPA policy templates as security baselines", configPath: "/app/claw-policies", automated: true }] } },
    { id: "PCI.3.1", framework: "pci_dss", title: "Protect Stored Account Data", description: "Stored account data is protected with strong cryptography.", category: "Data Protection", guidance: { learnMore: "Cardholder data at rest must be encrypted using strong cryptography. Primary Account Numbers must be rendered unreadable anywhere they are stored.", whyItMatters: "Stored unencrypted card data is a goldmine for attackers. A single breach can expose millions of card numbers.", requiredActions: [{ action: "Verify database encryption at rest (AES-256)", configPath: "/app/settings", automated: true }, { action: "Ensure no card data is stored in plain text in any table", configPath: "/app/compliance", automated: false }] } },
    { id: "PCI.4.1", framework: "pci_dss", title: "Encrypt Transmissions", description: "Protect cardholder data with strong cryptography during transmission over open networks.", category: "Data Protection", guidance: { learnMore: "All cardholder data transmitted over public networks must use TLS 1.2 or higher. This includes API calls, webhooks, and any external communication.", whyItMatters: "Data in transit on public networks is vulnerable to interception. TLS provides the encryption needed to protect it.", requiredActions: [{ action: "Verify TLS 1.2+ on all API endpoints", configPath: "/app/settings", automated: true }, { action: "Verify webhook delivery uses HTTPS only", configPath: "/app/settings", automated: true }] } },
    { id: "PCI.5.1", framework: "pci_dss", title: "Protect Against Malware", description: "Malicious software is prevented, detected, and addressed.", category: "Vulnerability Management", guidance: { learnMore: "Anti-malware solutions must be deployed on all systems commonly affected by malware. Claw sandbox isolation prevents malware spread.", whyItMatters: "Malware can steal cardholder data, install keyloggers, or create backdoors for persistent access to payment systems.", requiredActions: [{ action: "Verify claw sandbox isolation prevents malware spread", configPath: "/app/claw-fleet", automated: true }, { action: "Enable skill security scoring to block untrusted code", configPath: "/app/claw-policies", automated: true }] } },
    { id: "PCI.6.1", framework: "pci_dss", title: "Develop Secure Systems", description: "Bespoke and custom software is developed securely.", category: "Vulnerability Management", guidance: { learnMore: "Custom software must be developed using secure coding practices. Vulnerabilities must be identified and corrected before deployment.", whyItMatters: "Custom software vulnerabilities are unique to your environment and cannot be patched by vendors. Secure development prevents them.", requiredActions: [{ action: "Document secure development lifecycle", configPath: "/app/compliance", automated: false }, { action: "Implement code review procedures for policy changes", configPath: "/app/claw-policies", automated: false }] } },
    { id: "PCI.7.1", framework: "pci_dss", title: "Restrict Access by Business Need", description: "Access to system components and cardholder data is limited to those with a business need.", category: "Access Control", guidance: { learnMore: "Access must be restricted to the minimum necessary. Role-based access control must enforce business need-to-know for all cardholder data.", whyItMatters: "The more people with access to cardholder data, the larger the attack surface and the higher the breach risk.", requiredActions: [{ action: "Configure RBAC roles with least privilege", configPath: "/app/roles", automated: true }, { action: "Use team scoping to restrict data access", configPath: "/app/teams", automated: true }] } },
    { id: "PCI.8.1", framework: "pci_dss", title: "Identify Users and Authenticate Access", description: "Every user is assigned a unique ID and strong authentication is used.", category: "Access Control", guidance: { learnMore: "Unique IDs ensure accountability. Strong authentication (MFA for all access to cardholder data environments) prevents unauthorized access.", whyItMatters: "Shared accounts make forensic investigation impossible. MFA stops 99.9% of automated account compromise attacks.", requiredActions: [{ action: "Verify unique user IDs are enforced", configPath: "/app/teams", automated: true }, { action: "Enable MFA for users with access to payment systems", configPath: "/app/settings", automated: false }] } },
    { id: "PCI.10.1", framework: "pci_dss", title: "Log and Monitor All Access", description: "All access to system components and cardholder data is logged and monitored.", category: "Monitoring", guidance: { learnMore: "Comprehensive audit logging must capture all access to cardholder data, authentication events, and system administration actions.", whyItMatters: "Logging is how breaches are detected and investigated. Without logs, you cannot prove what happened during an incident.", requiredActions: [{ action: "Verify comprehensive audit logging is enabled", configPath: "/app/compliance", automated: true }, { action: "Configure log review procedures", configPath: "/app/compliance", automated: false }] } },
    { id: "PCI.11.1", framework: "pci_dss", title: "Regular Security Testing", description: "Security of systems and networks is tested regularly.", category: "Testing", guidance: { learnMore: "Regular vulnerability scans, penetration tests, and security assessments must be conducted to identify and address weaknesses.", whyItMatters: "Security testing finds vulnerabilities before attackers do. Regular testing ensures new vulnerabilities are caught quickly.", requiredActions: [{ action: "Use OPA policy test service to validate policy effectiveness", configPath: "/app/claw-policies?highlight=test-policy", automated: true }, { action: "Schedule regular penetration testing", configPath: "/app/compliance", automated: false }] } },
    { id: "PCI.12.1", framework: "pci_dss", title: "Information Security Policy", description: "An information security policy is established, published, and maintained.", category: "Policy", guidance: { learnMore: "A comprehensive security policy must address all PCI DSS requirements, be reviewed annually, and disseminated to all relevant personnel.", whyItMatters: "The security policy is the foundation of PCI compliance. Without it, controls lack organizational commitment and direction.", requiredActions: [{ action: "Document comprehensive information security policy", configPath: "/app/compliance", automated: false }, { action: "Review OPA policies align with organizational security policy", configPath: "/app/claw-policies", automated: false }] } },
  ];
}

// ════════════════════════════════════════════════════════════════════════════════
// NIST CSF 2.0 — Cybersecurity Framework
// ════════════════════════════════════════════════════════════════════════════════

export function getNistCsfControls(): ControlDef[] {
  return [
    { id: "GV.OC-01", framework: "nist_csf", title: "Organizational Context", description: "The organizational mission is understood and informs cybersecurity risk management.", category: "Govern", guidance: { learnMore: "The organization must understand its mission, stakeholder expectations, and legal/regulatory requirements to inform cybersecurity decisions.", whyItMatters: "Cybersecurity without business context leads to misallocated resources — protecting the wrong things while leaving critical assets exposed.", requiredActions: [{ action: "Document organizational mission and cybersecurity objectives", configPath: "/app/compliance", automated: false }] } },
    { id: "GV.RM-01", framework: "nist_csf", title: "Risk Management Strategy", description: "Risk management objectives are established and used to inform operational risk decisions.", category: "Govern", guidance: { learnMore: "A formal risk management strategy defines risk appetite, tolerance, and the process for identifying, assessing, and treating cybersecurity risks.", whyItMatters: "Without a risk strategy, organizations either over-invest in low-risk areas or under-invest in critical ones.", requiredActions: [{ action: "Document risk management strategy and risk appetite", configPath: "/app/compliance", automated: false }, { action: "Conduct periodic risk assessments", configPath: "/app/compliance", automated: false }] } },
    { id: "GV.RR-01", framework: "nist_csf", title: "Roles and Responsibilities", description: "Cybersecurity roles, responsibilities, and authorities are established.", category: "Govern", guidance: { learnMore: "Clear assignment of cybersecurity responsibilities ensures accountability. RBAC maps these roles to system permissions.", whyItMatters: "Ambiguous responsibilities mean security tasks fall through the cracks. Clear ownership drives consistent security outcomes.", requiredActions: [{ action: "Define cybersecurity roles using RBAC", configPath: "/app/roles", automated: true }, { action: "Assign team leads with security responsibilities", configPath: "/app/teams", automated: false }] } },
    { id: "ID.AM-01", framework: "nist_csf", title: "Asset Inventory", description: "Inventories of hardware, software, services, and data are maintained.", category: "Identify", guidance: { learnMore: "You cannot protect what you do not know about. Maintain current inventories of all technology assets, cloud services, data stores, and integrations.", whyItMatters: "Unknown assets are unprotected assets. Shadow IT and forgotten services are common breach entry points.", requiredActions: [{ action: "Review claw fleet inventory for all deployed agents", configPath: "/app/claw-fleet", automated: true }, { action: "Review data connections inventory", configPath: "/app/copilot", automated: true }, { action: "Document all telephony and third-party integrations", configPath: "/app/telephony", automated: true }] } },
    { id: "ID.RA-01", framework: "nist_csf", title: "Risk Assessment", description: "Vulnerabilities in assets are identified, validated, and recorded.", category: "Identify", guidance: { learnMore: "Regular vulnerability assessments identify weaknesses in systems, configurations, and processes before they can be exploited.", whyItMatters: "Every unidentified vulnerability is an open door for attackers. Systematic assessment closes those doors proactively.", requiredActions: [{ action: "Run OPA policy tests to identify policy gaps", configPath: "/app/claw-policies?highlight=test-policy", automated: true }, { action: "Review compliance controls for gaps", configPath: "/app/compliance", automated: true }] } },
    { id: "PR.AA-01", framework: "nist_csf", title: "Identity and Access Management", description: "Identities and credentials are managed for authorized users, services, and hardware.", category: "Protect", guidance: { learnMore: "Comprehensive IAM includes unique identifiers, strong credentials, lifecycle management (creation, modification, deactivation), and regular access reviews.", whyItMatters: "IAM is the gatekeeper for all system access. Weak IAM means weak everything else.", requiredActions: [{ action: "Configure RBAC with full permission catalog", configPath: "/app/roles", automated: true }, { action: "Set up team-based access scoping", configPath: "/app/teams", automated: true }, { action: "Enable session management with timeout", configPath: "/app/settings", automated: true }] } },
    { id: "PR.DS-01", framework: "nist_csf", title: "Data Security", description: "Data-at-rest and data-in-transit are protected.", category: "Protect", guidance: { learnMore: "All sensitive data must be encrypted at rest (AES-256) and in transit (TLS 1.2+). Access to data must be controlled and logged.", whyItMatters: "Data is the primary target of most attacks. Protecting data at every stage minimizes breach impact.", requiredActions: [{ action: "Verify encryption at rest and in transit", configPath: "/app/settings", automated: true }, { action: "Configure data classification on resources", configPath: "/app/claw-fleet", automated: false }, { action: "Enable Copilot query validation to prevent data exfiltration", configPath: "/app/copilot", automated: true }] } },
    { id: "PR.PS-01", framework: "nist_csf", title: "Platform Security", description: "Configuration management practices are established and applied.", category: "Protect", guidance: { learnMore: "All platform components must be configured securely using defined baselines. Changes must be controlled, tested, and documented.", whyItMatters: "Misconfigured systems are one of the top causes of breaches. Secure configuration baselines prevent drift.", requiredActions: [{ action: "Define OPA policy templates as configuration baselines", configPath: "/app/claw-policies", automated: true }, { action: "Enable configuration change logging in audit trail", configPath: "/app/compliance", automated: true }] } },
    { id: "DE.CM-01", framework: "nist_csf", title: "Continuous Monitoring", description: "Networks and network services are monitored to find potentially adverse events.", category: "Detect", guidance: { learnMore: "Continuous monitoring detects anomalous behavior, policy violations, and security events in real-time or near-real-time.", whyItMatters: "The faster a breach is detected, the lower the damage. Average time to detect without monitoring is 200+ days.", requiredActions: [{ action: "Enable OPA policy violation monitoring", configPath: "/app/claw-policies", automated: true }, { action: "Review audit events regularly in compliance dashboard", configPath: "/app/compliance", automated: true }] } },
    { id: "DE.AE-01", framework: "nist_csf", title: "Adverse Event Analysis", description: "Anomalies, indicators of compromise, and other potentially adverse events are analyzed.", category: "Detect", guidance: { learnMore: "Detected events must be analyzed to determine their nature, scope, and impact. Analysis should correlate events across multiple data sources.", whyItMatters: "Raw alerts without analysis lead to alert fatigue. Effective analysis turns noise into actionable intelligence.", requiredActions: [{ action: "Configure compliance report generation for regular analysis", configPath: "/app/compliance", automated: true }, { action: "Review security posture dashboard regularly", configPath: "/app/compliance", automated: true }] } },
    { id: "RS.MA-01", framework: "nist_csf", title: "Incident Management", description: "Incidents are managed to minimize impact.", category: "Respond", guidance: { learnMore: "Incident response procedures must cover detection, analysis, containment, eradication, and recovery. Roles and communication channels must be predefined.", whyItMatters: "A well-executed incident response can reduce breach impact by 60%. Without it, incidents escalate uncontrollably.", requiredActions: [{ action: "Document incident response procedures", configPath: "/app/compliance", automated: false }, { action: "Designate incident response team", configPath: "/app/teams", automated: false }, { action: "Configure claw quarantine capability for containment", configPath: "/app/claw-fleet", automated: true }] } },
    { id: "RC.RP-01", framework: "nist_csf", title: "Recovery Planning", description: "Recovery activities are performed to ensure operational availability.", category: "Recover", guidance: { learnMore: "Recovery plans must address restoring systems and data to normal operation. Plans must be tested regularly and updated based on lessons learned.", whyItMatters: "Without tested recovery plans, organizations may never fully recover from a major incident, leading to permanent data loss or business closure.", requiredActions: [{ action: "Document backup and recovery procedures", configPath: "/app/compliance", automated: false }, { action: "Verify database backup configuration", configPath: "/app/settings", automated: true }] } },
  ];
}

// ════════════════════════════════════════════════════════════════════════════════
// FedRAMP — Federal Risk and Authorization Management Program
// ════════════════════════════════════════════════════════════════════════════════

export function getFedrampControls(): ControlDef[] {
  return [
    { id: "AC-1", framework: "fedramp", title: "Access Control Policy and Procedures", description: "Develop, document, disseminate, and maintain access control policies.", category: "Access Control", guidance: { learnMore: "A formal access control policy defines who can access what resources, under what conditions, and how access is granted, reviewed, and revoked.", whyItMatters: "FedRAMP requires documented policies for every control family. The access control policy is foundational for ATO.", requiredActions: [{ action: "Document access control policy", configPath: "/app/compliance", automated: false }, { action: "Configure RBAC to enforce the policy", configPath: "/app/roles", automated: true }] } },
    { id: "AC-2", framework: "fedramp", title: "Account Management", description: "Manage system accounts including creating, enabling, modifying, disabling, and removing accounts.", category: "Access Control", guidance: { learnMore: "All accounts must have a defined lifecycle. Temporary accounts must expire. Unused accounts must be disabled. All changes must be logged.", whyItMatters: "Orphaned accounts are a primary attack vector. Account management ensures only current, authorized users have access.", requiredActions: [{ action: "Configure team-based user management", configPath: "/app/teams", automated: true }, { action: "Enable RBAC audit trail for account changes", configPath: "/app/compliance", automated: true }] } },
    { id: "AC-3", framework: "fedramp", title: "Access Enforcement", description: "Enforce approved authorizations for logical access to system resources.", category: "Access Control", guidance: { learnMore: "The system must enforce access control decisions made by the authorization policy. RBAC middleware and OPA policies provide this enforcement.", whyItMatters: "Policies without technical enforcement are just suggestions. Access enforcement turns policy into reality.", requiredActions: [{ action: "Verify RBAC middleware is applied to all routes", configPath: "/app/roles", automated: true }, { action: "Verify OPA policies enforce access decisions for claw agents", configPath: "/app/claw-policies", automated: true }] } },
    { id: "AC-6", framework: "fedramp", title: "Least Privilege", description: "Employ the principle of least privilege, allowing only authorized accesses necessary for users.", category: "Access Control", guidance: { learnMore: "Users must receive the minimum access needed. Privileged functions must be restricted. All privilege use must be audited.", whyItMatters: "Excessive privilege is the most exploited misconfiguration. Least privilege limits blast radius of compromised accounts.", requiredActions: [{ action: "Review role assignments for excessive privilege", configPath: "/app/roles", automated: false }, { action: "Use team-scoped roles instead of org-wide", configPath: "/app/teams", automated: false }] } },
    { id: "AU-2", framework: "fedramp", title: "Audit Events", description: "Identify the types of events that the system must audit.", category: "Audit & Accountability", guidance: { learnMore: "Define which events must be logged: authentication, authorization, data access, configuration changes, policy decisions, and administrative actions.", whyItMatters: "If the right events are not logged, investigations cannot determine what happened during an incident.", requiredActions: [{ action: "Verify comprehensive audit event capture", configPath: "/app/compliance", automated: true }, { action: "Document auditable event types", configPath: "/app/compliance", automated: false }] } },
    { id: "AU-6", framework: "fedramp", title: "Audit Review, Analysis, and Reporting", description: "Review and analyze audit records for indications of inappropriate or unusual activity.", category: "Audit & Accountability", guidance: { learnMore: "Audit logs must be reviewed regularly (at minimum weekly). Anomalous activity must be investigated. Findings must be reported to appropriate personnel.", whyItMatters: "Logs are only valuable if someone reads them. Regular review turns passive logging into active threat detection.", requiredActions: [{ action: "Use compliance dashboard for audit review", configPath: "/app/compliance", automated: true }, { action: "Establish weekly audit review procedures", configPath: "/app/compliance", automated: false }] } },
    { id: "CM-2", framework: "fedramp", title: "Baseline Configuration", description: "Develop, document, and maintain baseline configurations for the system.", category: "Configuration Management", guidance: { learnMore: "Documented baseline configurations define the approved state of all system components. Deviations must be detected and resolved.", whyItMatters: "Without baselines, you cannot detect unauthorized changes. Configuration drift is a leading cause of security incidents.", requiredActions: [{ action: "Define OPA policy baselines for system configuration", configPath: "/app/claw-policies", automated: true }, { action: "Document approved system configuration baselines", configPath: "/app/compliance", automated: false }] } },
    { id: "CM-3", framework: "fedramp", title: "Configuration Change Control", description: "Determine, document, approve, and track changes to the system.", category: "Configuration Management", guidance: { learnMore: "All configuration changes must go through a formal change control process: request, review, approve, implement, verify, document.", whyItMatters: "Uncontrolled changes cause 80% of outages. Change control prevents unauthorized modifications to production systems.", requiredActions: [{ action: "Track configuration changes in RBAC audit trail", configPath: "/app/compliance", automated: true }, { action: "Establish change approval workflow for policy updates", configPath: "/app/claw-policies", automated: false }] } },
    { id: "IR-1", framework: "fedramp", title: "Incident Response Policy", description: "Develop, document, disseminate, and maintain incident response policies and procedures.", category: "Incident Response", guidance: { learnMore: "A comprehensive IR policy defines organizational approach to incident handling including preparation, detection, analysis, containment, eradication, and recovery.", whyItMatters: "FedRAMP requires a documented IR policy and regular testing. IR capability is assessed during every FedRAMP assessment.", requiredActions: [{ action: "Document incident response policy and procedures", configPath: "/app/compliance", automated: false }, { action: "Configure security event monitoring for IR", configPath: "/app/compliance", automated: true }] } },
    { id: "IR-4", framework: "fedramp", title: "Incident Handling", description: "Implement an incident handling capability that includes preparation, detection, analysis, containment, eradication, and recovery.", category: "Incident Response", guidance: { learnMore: "Operational incident handling requires trained personnel, documented procedures, communication plans, and tools for containment (like claw quarantine).", whyItMatters: "Effective incident handling reduces average breach cost by $1.5M. Speed of containment directly correlates with damage reduction.", requiredActions: [{ action: "Enable claw quarantine capability for containment", configPath: "/app/claw-fleet", automated: true }, { action: "Designate incident response roles", configPath: "/app/teams", automated: false }] } },
    { id: "CA-7", framework: "fedramp", title: "Continuous Monitoring", description: "Develop a continuous monitoring strategy and implement a continuous monitoring program.", category: "Security Assessment", guidance: { learnMore: "Continuous monitoring provides ongoing awareness of security posture, vulnerabilities, and threats through automated and manual processes.", whyItMatters: "Point-in-time assessments become stale within weeks. Continuous monitoring ensures ongoing compliance and security awareness.", requiredActions: [{ action: "Configure compliance dashboard for continuous monitoring", configPath: "/app/compliance", automated: true }, { action: "Enable OPA policy evaluation monitoring", configPath: "/app/claw-policies", automated: true }, { action: "Schedule regular compliance report generation", configPath: "/app/compliance", automated: false }] } },
  ];
}

