// ════════════════════════════════════════════════════════════════════════════════
// ISO 42001:2023 — Artificial Intelligence Management System
// ════════════════════════════════════════════════════════════════════════════════

export function getIso42001Controls(): ControlDef[] {
  return [
    // ── AI Governance ──
    { id: "AI.4.1", framework: "iso42001", title: "AI policy", description: "Establish AI use policy defining acceptable/prohibited uses, risk thresholds, human oversight requirements.", category: "AI Governance", guidance: { learnMore: "An organizational AI policy sets the boundaries for how AI systems may be used, which use cases are prohibited, acceptable risk levels, and when human oversight is mandatory. This is the foundational document for all AI governance.", whyItMatters: "Without a clear AI policy, teams deploy AI systems inconsistently, creating liability exposure, reputational risk, and potential regulatory violations as AI regulations tighten globally.", requiredActions: [{ action: "Create and publish an AI acceptable use policy", configPath: "/app/claw-policies", automated: false }, { action: "Define risk thresholds for AI system deployment", configPath: "/app/claw-policies", automated: false }, { action: "Configure human oversight requirements in agent policies", configPath: "/app/claw-policies", automated: true }] } },
    { id: "AI.4.2", framework: "iso42001", title: "AI risk assessment", description: "Assess risks specific to AI systems including bias, hallucination, privacy, safety.", category: "AI Governance", guidance: { learnMore: "AI systems introduce unique risks beyond traditional IT: model hallucinations generating false information, algorithmic bias producing discriminatory outcomes, privacy risks from training data, and safety concerns from autonomous actions.", whyItMatters: "AI-specific risks are fundamentally different from traditional IT risks. Standard risk assessments miss hallucination rates, bias propagation, and emergent behaviors that can cause significant harm.", requiredActions: [{ action: "Conduct AI-specific risk assessment for each deployed agent", configPath: "/app/claw-fleet", automated: false }, { action: "Document hallucination mitigation strategies", configPath: "/app/compliance", automated: false }, { action: "Enable bias detection monitoring on agent outputs", configPath: "/app/claw-fleet", automated: true }] } },
    { id: "AI.4.3", framework: "iso42001", title: "AI roles and responsibilities", description: "Designate AI governance roles (AI ethics officer, model validators, data stewards).", category: "AI Governance", guidance: { learnMore: "Effective AI governance requires designated roles: an AI ethics officer to oversee responsible AI use, model validators to verify AI system behavior, and data stewards to manage training data quality and provenance.", whyItMatters: "Without clear AI governance roles, accountability gaps emerge. No one owns bias monitoring, model validation falls through the cracks, and AI incidents have no clear escalation path.", requiredActions: [{ action: "Create AI Ethics Officer role in the organization", configPath: "/app/roles", automated: false }, { action: "Assign model validation responsibilities to team members", configPath: "/app/roles", automated: false }, { action: "Designate data stewards for AI training data governance", configPath: "/app/roles", automated: false }] } },
    { id: "AI.4.4", framework: "iso42001", title: "AI strategy and objectives", description: "Align AI deployment with organizational objectives and values.", category: "AI Governance", guidance: { learnMore: "AI deployments must support organizational goals and reflect corporate values. Each AI system should have a documented purpose, success metrics, and alignment with the organization's mission and ethical commitments.", whyItMatters: "AI deployed without strategic alignment wastes resources and creates risk. Systems that conflict with organizational values erode trust with customers, employees, and regulators.", requiredActions: [{ action: "Document AI deployment objectives for each agent", configPath: "/app/claw-fleet", automated: false }, { action: "Align agent policies with organizational values", configPath: "/app/claw-policies", automated: false }, { action: "Review AI strategy alignment quarterly", configPath: "/app/compliance", automated: false }] } },

    // ── AI System Lifecycle ──
    { id: "AI.5.1", framework: "iso42001", title: "Data management", description: "Govern training data quality, provenance, bias detection, consent for AI training data.", category: "AI System Lifecycle", guidance: { learnMore: "Training data is the foundation of AI system quality. Organizations must track data provenance, ensure data quality, detect and mitigate biases in datasets, and verify proper consent for data used in AI training.", whyItMatters: "Poor training data produces poor AI outcomes. Biased data produces biased decisions. Using data without consent creates legal liability under GDPR, CCPA, and emerging AI regulations.", requiredActions: [{ action: "Document data sources and provenance for AI training", configPath: "/app/copilot", automated: false }, { action: "Implement data quality validation pipelines", configPath: "/app/copilot", automated: true }, { action: "Verify consent records for AI training data", configPath: "/app/compliance", automated: false }] } },
    { id: "AI.5.2", framework: "iso42001", title: "Model development", description: "Document model selection, training procedures, validation methods.", category: "AI System Lifecycle", guidance: { learnMore: "Model development must be documented including the rationale for model selection, training procedures used, hyperparameter choices, and validation methodology. This creates an audit trail for model decisions.", whyItMatters: "Undocumented model development makes it impossible to reproduce results, debug failures, or demonstrate compliance to auditors. Documentation is essential for accountability.", requiredActions: [{ action: "Document model selection rationale for each agent", configPath: "/app/claw-fleet", automated: false }, { action: "Record training procedures and configurations", configPath: "/app/compliance", automated: false }, { action: "Maintain model development logs", configPath: "/app/compliance", automated: true }] } },
    { id: "AI.5.3", framework: "iso42001", title: "Model validation and testing", description: "Test for accuracy, bias, robustness, adversarial inputs before deployment.", category: "AI System Lifecycle", guidance: { learnMore: "Before deployment, AI models must be validated for accuracy against benchmarks, tested for bias across protected categories, evaluated for robustness under edge cases, and assessed for vulnerability to adversarial inputs.", whyItMatters: "Deploying untested AI models is like shipping software without QA. Inaccurate models make wrong decisions, biased models discriminate, and vulnerable models can be manipulated by attackers.", requiredActions: [{ action: "Run OPA policy tests to validate agent behavior", configPath: "/app/claw-policies?highlight=test-policy", automated: true }, { action: "Conduct bias testing across demographic categories", configPath: "/app/compliance", automated: false }, { action: "Test agent responses to adversarial inputs", configPath: "/app/claw-fleet", automated: false }] } },
    { id: "AI.5.4", framework: "iso42001", title: "Deployment and monitoring", description: "Monitor model performance, drift detection, automated rollback capability.", category: "AI System Lifecycle", guidance: { learnMore: "Deployed AI systems must be continuously monitored for performance degradation, data drift (input distribution changes), concept drift (relationship changes), and anomalous behavior with automated rollback capability.", whyItMatters: "AI models degrade over time as the world changes. Without monitoring, models silently become less accurate, more biased, or start producing harmful outputs without anyone noticing.", requiredActions: [{ action: "Configure agent performance monitoring dashboards", configPath: "/app/claw-fleet", automated: true }, { action: "Enable drift detection alerts on agent metrics", configPath: "/app/claw-fleet", automated: true }, { action: "Set up automated rollback procedures for underperforming agents", configPath: "/app/claw-fleet", automated: false }] } },
    { id: "AI.5.5", framework: "iso42001", title: "Decommissioning", description: "Procedures for retiring AI models, data cleanup, stakeholder notification.", category: "AI System Lifecycle", guidance: { learnMore: "When AI systems are retired, organizations must follow documented procedures for model archival, training data cleanup or retention, stakeholder notification, and transition planning to replacement systems.", whyItMatters: "Improper decommissioning leaves orphaned data, confuses stakeholders who depend on the system, and creates compliance gaps when audit trails are lost.", requiredActions: [{ action: "Document AI system decommissioning procedures", configPath: "/app/compliance", automated: false }, { action: "Configure data retention policies for retired agents", configPath: "/app/claw-fleet", automated: false }, { action: "Create stakeholder notification templates for AI retirement", configPath: "/app/compliance", automated: false }] } },

    // ── AI Ethics and Impact ──
    { id: "AI.6.1", framework: "iso42001", title: "Fairness and bias", description: "Implement bias detection and mitigation across AI systems.", category: "AI Ethics and Impact", guidance: { learnMore: "AI systems must be regularly assessed for bias in their outputs across protected characteristics (race, gender, age, disability). Detection mechanisms must be paired with mitigation strategies and ongoing monitoring.", whyItMatters: "Biased AI amplifies discrimination at scale. A biased hiring model can discriminate against thousands of applicants. Regulatory penalties and reputational damage from AI bias are severe and increasing.", requiredActions: [{ action: "Implement bias detection metrics for agent outputs", configPath: "/app/claw-fleet", automated: true }, { action: "Document bias mitigation strategies per agent", configPath: "/app/compliance", automated: false }, { action: "Schedule regular bias audits for production agents", configPath: "/app/compliance", automated: false }] } },
    { id: "AI.6.2", framework: "iso42001", title: "Transparency and explainability", description: "Provide explanations for AI decisions, especially those affecting individuals.", category: "AI Ethics and Impact", guidance: { learnMore: "AI-driven decisions that affect individuals must be explainable. Users should understand why the AI made a particular recommendation or decision, what data was used, and how to contest the outcome.", whyItMatters: "Opaque AI decisions erode trust and violate regulations like GDPR Article 22 (right not to be subject to automated decision-making). Explainability is becoming a legal requirement globally.", requiredActions: [{ action: "Enable decision logging with reasoning for all agents", configPath: "/app/claw-fleet", automated: true }, { action: "Provide explanation endpoints for AI-driven decisions", configPath: "/app/compliance", automated: false }, { action: "Document transparency measures in compliance records", configPath: "/app/compliance", automated: false }] } },
    { id: "AI.6.3", framework: "iso42001", title: "Human oversight", description: "Maintain meaningful human control over AI decisions with escalation paths.", category: "AI Ethics and Impact", guidance: { learnMore: "Humans must retain meaningful control over AI systems, especially for high-stakes decisions. This includes human-in-the-loop processes, escalation paths for uncertain situations, and the ability to override AI recommendations.", whyItMatters: "Fully autonomous AI without human oversight creates unacceptable risk for consequential decisions. Human oversight catches errors, provides accountability, and maintains trust.", requiredActions: [{ action: "Configure human-in-the-loop policies for high-stakes agents", configPath: "/app/claw-policies", automated: true }, { action: "Define escalation paths for AI uncertainty situations", configPath: "/app/claw-policies", automated: false }, { action: "Enable manual override capability for all agent decisions", configPath: "/app/claw-fleet", automated: true }] } },
    { id: "AI.6.4", framework: "iso42001", title: "AI impact assessment", description: "Conduct impact assessments for AI systems processing personal data or making consequential decisions.", category: "AI Ethics and Impact", guidance: { learnMore: "AI Impact Assessments (AIIAs) evaluate the potential effects of AI systems on individuals, groups, and society. They are required for systems processing personal data or making decisions with legal or significant effects.", whyItMatters: "Impact assessments identify risks before deployment, not after harm occurs. They are increasingly required by regulation (EU AI Act, GDPR DPIA) and demonstrate due diligence.", requiredActions: [{ action: "Conduct AI impact assessments for each production agent", configPath: "/app/compliance", automated: false }, { action: "Document assessment outcomes and mitigation plans", configPath: "/app/compliance", automated: false }, { action: "Review impact assessments annually or upon significant changes", configPath: "/app/compliance", automated: false }] } },

    // ── AI Security ──
    { id: "AI.7.1", framework: "iso42001", title: "AI-specific threats", description: "Protect against prompt injection, model extraction, data poisoning, adversarial attacks.", category: "AI Security", guidance: { learnMore: "AI systems face unique attack vectors: prompt injection (manipulating AI via crafted inputs), model extraction (stealing model weights), data poisoning (corrupting training data), and adversarial attacks (inputs designed to cause misclassification).", whyItMatters: "Traditional security controls do not protect against AI-specific attacks. Prompt injection can bypass all safety guardrails. Data poisoning can corrupt an entire model without detection.", requiredActions: [{ action: "Configure OPA policies to detect and block prompt injection", configPath: "/app/claw-policies", automated: true }, { action: "Enable input validation and sanitization on all agents", configPath: "/app/claw-fleet", automated: true }, { action: "Document AI threat model including AI-specific attack vectors", configPath: "/app/compliance", automated: false }] } },
    { id: "AI.7.2", framework: "iso42001", title: "Supply chain security for AI", description: "Vet AI model providers, skill marketplaces, training data sources.", category: "AI Security", guidance: { learnMore: "The AI supply chain includes model providers, pre-trained model repositories, skill and plugin marketplaces, and training data sources. Each must be vetted for security, reliability, and compliance.", whyItMatters: "A compromised AI model or poisoned training dataset from an unvetted supplier can undermine the security of the entire system. Supply chain attacks on AI are increasing.", requiredActions: [{ action: "Vet and approve AI model providers before use", configPath: "/app/compliance", automated: false }, { action: "Enable skill security scoring for marketplace skills", configPath: "/app/claw-policies", automated: true }, { action: "Document approved AI supply chain sources", configPath: "/app/compliance", automated: false }] } },
    { id: "AI.7.3", framework: "iso42001", title: "AI system isolation", description: "Sandbox AI agent execution, prevent unauthorized data access between agents.", category: "AI Security", guidance: { learnMore: "AI agents must execute in isolated sandboxes with defined resource limits, network restrictions, and data access boundaries. Agents must not be able to access each other's data or escalate privileges.", whyItMatters: "Without isolation, a compromised or misbehaving AI agent can access all data in the system, affect other agents, or use excessive resources. Sandboxing contains the blast radius.", requiredActions: [{ action: "Verify agent sandbox isolation is configured", configPath: "/app/claw-fleet", automated: true }, { action: "Configure OPA network policies to restrict agent communication", configPath: "/app/claw-policies", automated: true }, { action: "Set resource limits on all agent sandboxes", configPath: "/app/claw-fleet", automated: true }] } },

    // ── AI Compliance ──
    { id: "AI.8.1", framework: "iso42001", title: "Regulatory monitoring", description: "Track evolving AI regulations (EU AI Act, US Executive Orders, sector-specific rules).", category: "AI Compliance", guidance: { learnMore: "The AI regulatory landscape is rapidly evolving. Organizations must monitor and assess new regulations including the EU AI Act, US AI Executive Orders, sector-specific AI rules (healthcare, finance), and state-level AI legislation.", whyItMatters: "AI regulations are being enacted faster than any previous technology regulation cycle. Non-compliance can result in fines up to 7% of global revenue under the EU AI Act.", requiredActions: [{ action: "Establish AI regulatory monitoring process", configPath: "/app/compliance", automated: false }, { action: "Document applicable AI regulations and requirements", configPath: "/app/compliance", automated: false }, { action: "Review agent configurations against new regulations quarterly", configPath: "/app/claw-fleet", automated: false }] } },
    { id: "AI.8.2", framework: "iso42001", title: "AI incident reporting", description: "Procedures for reporting AI-related incidents (hallucinations causing harm, bias incidents).", category: "AI Compliance", guidance: { learnMore: "AI-specific incidents (harmful hallucinations, biased decisions, privacy breaches from AI processing, autonomous actions causing damage) require dedicated reporting procedures distinct from traditional IT incidents.", whyItMatters: "AI incidents are increasingly subject to mandatory reporting requirements. The EU AI Act requires reporting serious incidents within 15 days. Without procedures, reporting deadlines are missed.", requiredActions: [{ action: "Document AI incident reporting procedures", configPath: "/app/compliance", automated: false }, { action: "Configure AI incident detection alerts", configPath: "/app/claw-fleet", automated: true }, { action: "Create AI incident response playbooks", configPath: "/app/compliance", automated: false }] } },
    { id: "AI.8.3", framework: "iso42001", title: "Third-party AI audit", description: "Enable external audit of AI systems, provide audit trail and model documentation.", category: "AI Compliance", guidance: { learnMore: "Organizations must be prepared for external audits of their AI systems. This requires comprehensive audit trails, model documentation (model cards), training data records, decision logs, and performance metrics.", whyItMatters: "External AI audits are becoming mandatory under the EU AI Act for high-risk systems. Without audit readiness, organizations face compliance gaps, regulatory penalties, and loss of market access.", requiredActions: [{ action: "Maintain comprehensive audit trail for all agent activities", configPath: "/app/compliance", automated: true }, { action: "Create model cards documenting each agent's capabilities and limitations", configPath: "/app/claw-fleet", automated: false }, { action: "Enable external auditor read-only access configuration", configPath: "/app/settings", automated: false }] } },
  ];
}

// ════════════════════════════════════════════════════════════════════════════════
// Lookup function — returns controls for any framework
// ════════════════════════════════════════════════════════════════════════════════

// Import detailed versions from the extended file for PCI/NIST/FedRAMP
import {
  getPciDssControls as getPciDssDetailedControls,
  getNistCsfControls as getNistCsfDetailedControls,
  getFedrampControls as getFedrampDetailedControls,
} from "./compliance-frameworks-extended";

// Import CCPA/SOX/CIS/CSA STAR from the extra file
import {
  getCcpaControls,
  getSoxControls,
  getCisControls,
  getCsaStarControls,
} from "./compliance-frameworks-extra";

export function getExtendedControls(framework: string): ControlDef[] {
  switch (framework) {
    case "cmmc": return getCmmcControls();
    case "hipaa": return getHipaaControls();
    case "gdpr": return getGdprControls();
    case "pci_dss": return getPciDssDetailedControls() as any;
    case "nist_csf": return getNistCsfDetailedControls() as any;
    case "fedramp": return getFedrampDetailedControls() as any;
    case "ccpa": return getCcpaControls();
    case "sox": return getSoxControls();
    case "cis": return getCisControls();
    case "csa_star": return getCsaStarControls();
    case "iso42001": return getIso42001Controls();
    default: return [];
  }
}
